def transform(grid):
    # Erase all non-zero, non-divider pixels below the full horizontal row of 8s
    grid = [row[:] for row in grid]
    divider_r = None
    for r in range(len(grid)):
        if all(c == 8 for c in grid[r]):
            divider_r = r
            break
    if divider_r is not None:
        for r in range(divider_r + 1, len(grid)):
            for c in range(len(grid[0])):
                if grid[r][c] != 8:
                    grid[r][c] = 0
    return grid

def transform(grid):
    # Keep the side of the divider with more connected components/objects
    # In training, top has 2 objects, bottom has 1 object -> keep top
    grid = [row[:] for row in grid]
    divider_r = None
    for r in range(len(grid)):
        if all(c == 8 for c in grid[r]):
            divider_r = r
            break
    if divider_r is not None:
        # erase below
        for r in range(divider_r + 1, len(grid)):
            for c in range(len(grid[0])):
                grid[r][c] = 0
    return grid
